// ============================================================
// EXTRACT INPUT: Извлечение данных из Telegram
// ============================================================

const input = $json;

// Обработка обычного сообщения или callback
const message = input.message || input.callback_query?.message || {};
const callbackData = input.callback_query?.data || null;
const from = input.message?.from || input.callback_query?.from || {};

return {
  // Идентификаторы
  chat_id: String(message.chat?.id || from.id || ''),
  user_id: String(from.id || ''),
  message_id: message.message_id,

  // Данные пользователя
  first_name: from.first_name || '',
  last_name: from.last_name || '',
  username: from.username || '',
  language_code: from.language_code || 'ru',

  // Сообщение
  user_message: message.text || callbackData || '',
  callback_data: callbackData,
  is_callback: !!callbackData,

  // Timestamp
  timestamp: new Date().toISOString()
};

// ============================================================
// FALLBACK: Если БД недоступна - работаем stateless
// ============================================================

const input = $('Extract Input').first().json;

console.log('⚠️ Database unavailable, using stateless mode');

return {
  ...input,
  session_id: 'stateless_' + input.user_id,
  session_status: 'active',
  is_new_user: true,
  known_data: {},
  chat_history: [],
  vacancies: [],
  db_available: false,
  language: 'ru'
};

// ============================================================
// MERGE CONTEXT: Объединяем данные сессии с входными данными
// ============================================================

const input = $('Extract Input').first().json;
const session = $json[0] || $json;

// Форматируем историю чата для промпта
let historyText = 'История диалога пуста (новый пользователь)';
try {
  const history = session.chat_history || [];
  if (Array.isArray(history) && history.length > 0) {
    historyText = history
      .slice(0, 5)
      .map(m => `${m.role === 'user' ? 'Кандидат' : 'Бот'}: ${m.content}`)
      .join('\n');
  }
} catch (e) {
  historyText = 'История недоступна';
}

// Форматируем вакансии
let vacanciesText = 'Вакансии загружаются...';
try {
  const vacancies = session.vacancies || [];
  if (Array.isArray(vacancies) && vacancies.length > 0) {
    vacanciesText = vacancies
      .map(v => `• ${v.title}: ${v.salary || 'по договорённости'}`)
      .join('\n');
  }
} catch (e) {
  vacanciesText = 'Горничная, Администратор, Официант';
}

return {
  // Идентификаторы
  chat_id: input.chat_id,
  user_id: input.user_id,
  session_id: session.session_id || 'unknown',

  // Данные пользователя
  first_name: input.first_name,
  username: input.username,
  language: session.language || 'ru',

  // Сообщение
  user_message: input.user_message,
  callback_data: input.callback_data,
  is_callback: input.is_callback,

  // Сессия
  session_status: session.session_status || 'active',
  is_new_user: session.is_new_user || false,
  known_data: session.known_data || {},

  // Контекст для LLM
  chat_history: session.chat_history || [],
  chat_history_text: historyText,
  vacancies: session.vacancies || [],
  vacancies_text: vacanciesText,

  // Флаги
  db_available: true
};

// ============================================================
// REGEX PRE-ROUTER: Быстрая маршрутизация без LLM
// Экономит ~40% вызовов API
// ============================================================

const input = $json;
const msg = (input.user_message || '').toLowerCase().trim();
const callback = input.callback_data || '';

let route = null;
let confidence = 1.0;
let needsLlm = true;

// === CALLBACK QUERIES ===
if (callback) {
  if (callback.startsWith('lang_')) {
    route = 'LANGUAGE';
    needsLlm = false;
  }
}

// === COMMANDS ===
else if (msg === '/start' || msg === 'start') {
  route = 'GREETING';
  needsLlm = false;
}
else if (msg === '/cancel' || msg === '/stop' || msg === 'отмена' || msg === 'стоп') {
  route = 'CANCEL';
  needsLlm = false;
}
else if (msg === '/restart' || msg === '/reset' || msg === 'заново' || msg === 'начать заново') {
  route = 'GREETING';
  needsLlm = false;
}
else if (msg === '/help' || msg === 'помощь' || msg === 'помоги') {
  route = 'FAQ';
  needsLlm = false;
}

// === GREETINGS ===
else if (/^(привет|здравствуй|салам|хай|hello|hi|добрый\s*(день|вечер|утро))/.test(msg)) {
  // Если новый пользователь - приветствие, иначе интервью
  route = input.is_new_user ? 'GREETING' : 'INTERVIEW';
  needsLlm = false;
  confidence = 0.9;
}

// === LANGUAGE SELECTION ===
else if (/^(русский|узбекский|кыргызский|таджикский|рус|узб|кырг|тадж)/i.test(msg)) {
  route = 'LANGUAGE';
  needsLlm = false;
}

// === FAQ KEYWORDS ===
else if (/^(вакансии|зарплата|график|условия|где работа|какие вакансии)/i.test(msg)) {
  route = 'FAQ';
  needsLlm = false;
  confidence = 0.85;
}

// === SHORT ANSWERS (likely interview) ===
else if (msg.length < 50 && !input.is_new_user) {
  // Короткие ответы от существующего пользователя - скорее всего интервью
  route = 'INTERVIEW';
  needsLlm = false;
  confidence = 0.8;
}

return {
  ...input,
  fast_route: route,
  route_confidence: confidence,
  needs_llm: needsLlm
};

// Parse LLM response
const input = $('Regex Pre-Router').first().json;
const llmResponse = ($json.text || $json.content || 'INTERVIEW').toUpperCase().trim();

const validRoutes = ['GREETING', 'INTERVIEW', 'FAQ', 'ESCALATION', 'CANCEL', 'LANGUAGE'];
let route = validRoutes.includes(llmResponse) ? llmResponse : 'INTERVIEW';

return {
  ...input,
  route_category: route,
  route_source: 'llm'
};

// LLM Error Fallback - default to INTERVIEW
const input = $('Regex Pre-Router').first().json;

console.log('⚠️ LLM Router error, defaulting to INTERVIEW');

return {
  ...input,
  route_category: 'INTERVIEW',
  route_source: 'fallback'
};

// Fast Route Result - use regex route
const input = $json;

return {
  ...input,
  route_category: input.fast_route || 'INTERVIEW',
  route_source: 'regex'
};

// ============================================================
// GREETING HANDLER: Статическое приветствие (без LLM)
// ============================================================

const input = $json;

const greetingMessage = `👋 Здравствуйте${input.first_name ? ', ' + input.first_name : ''}! Добро пожаловать в BestHotel!

Я — AI-рекрутер, и я помогу вам узнать о наших вакансиях и пройти короткое собеседование. 🤝

Мы ищем сотрудников для работы в отелях: горничные, администраторы, официанты и другие позиции.

🌍 Выберите удобный язык общения:`;

return {
  ...input,
  response_message: greetingMessage,
  show_language_buttons: true,
  interview_complete: false,
  extracted_data: {}
};

