// ============================================================
// INTERVIEW RESPONSE PARSER
// ============================================================

const input = $('Route Switch').first().json;
const llmResponse = $json;

let parsed = {
  message: 'Расскажите немного о себе. Как вас зовут? 🤝',
  extracted_data: {},
  interview_complete: false
};

try {
  const rawOutput = llmResponse.text || llmResponse.content || '';
  const cleanJson = String(rawOutput).replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const jsonMatch = cleanJson.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = { ...parsed, ...JSON.parse(jsonMatch[0]) };
  }
} catch (e) {
  console.log('Parse error:', e.message);
}

// Merge known data
const mergedData = { ...(input.known_data || {}) };
if (parsed.extracted_data) {
  Object.entries(parsed.extracted_data).forEach(([key, value]) => {
    if (value && value !== null && value !== 'null' && value !== '') {
      mergedData[key] = value;
    }
  });
}

// Phone validation
if (mergedData.phone) {
  let phone = String(mergedData.phone).replace(/[\s\-\(\)]/g, '');
  if (phone.startsWith('8') && phone.length === 11) phone = '+7' + phone.substring(1);
  else if (phone.startsWith('7') && phone.length === 11) phone = '+' + phone;
  if (/^\+7\d{10}$/.test(phone)) mergedData.phone = phone;
  else mergedData.phone = null;
}

return {
  ...input,
  response_message: parsed.message,
  extracted_data: mergedData,
  known_data: mergedData,
  interview_complete: parsed.interview_complete || false,
  show_language_buttons: false
};

// Interview LLM Error Fallback
const input = $('Route Switch').first().json;

return {
  ...input,
  response_message: 'Извините, произошла техническая ошибка. 🔧 Пожалуйста, повторите ваше сообщение.',
  extracted_data: input.known_data || {},
  interview_complete: false,
  show_language_buttons: false
};

// ============================================================
// FAQ HANDLER: Ответы на частые вопросы
// ============================================================

const input = $json;
const msg = (input.user_message || '').toLowerCase();

let response = '';

if (msg.includes('вакансии') || msg.includes('работа')) {
  response = '🏨 Наши актуальные вакансии:

' + (input.vacancies_text || '• Горничная
• Администратор
• Официант') + '

Хотите пройти собеседование? Напишите "Да"!';
} else if (msg.includes('зарплата') || msg.includes('оплата')) {
  response = '💰 Зарплата зависит от позиции и опыта:

• Горничная: от 45,000 ₽
• Администратор: от 55,000 ₽
• Официант: от 50,000 ₽

Оплата стабильная, 2 раза в месяц!';
} else if (msg.includes('график') || msg.includes('режим')) {
  response = '📅 Графики работы:

• 2/2 или 5/2
• Смены по 8-12 часов
• Возможны ночные смены

Конкретный график обсуждается индивидуально.';
} else if (msg.includes('документ')) {
  response = '📋 Для работы нужно ОДНО из двух:

1️⃣ Приложение "Амина" — быстро и удобно!
2️⃣ Полный пакет: паспорт + миграционная карта + регистрация

Если документы в процессе оформления — тоже напишите!';
} else {
  response = '❓ Я могу ответить на вопросы о:

• Вакансиях
• Зарплате
• Графике работы
• Документах

Или напишите "Собеседование" чтобы начать!';
}

return {
  ...input,
  response_message: response,
  show_language_buttons: false,
  interview_complete: false,
  extracted_data: input.known_data || {}
};

// ============================================================
// CANCEL HANDLER: Отмена/сброс сессии
// ============================================================

const input = $json;

return {
  ...input,
  response_message: '🔄 Сессия сброшена.\n\nНапишите /start чтобы начать заново.',
  show_language_buttons: false,
  interview_complete: false,
  extracted_data: {},
  reset_session: true
};

// ============================================================
// LANGUAGE HANDLER: Обработка выбора языка
// ============================================================

const input = $json;
const callback = input.callback_data || '';
const msg = (input.user_message || '').toLowerCase();

// Определяем выбранный язык
let selectedLang = 'ru';
let langName = 'Русский';

if (callback === 'lang_uz' || msg.includes('узбек') || msg.includes('uzbek')) {
  selectedLang = 'uz';
  langName = "O'zbek tili";
} else if (callback === 'lang_kg' || msg.includes('кыргыз') || msg.includes('kyrgyz')) {
  selectedLang = 'kg';
  langName = 'Кыргыз тили';
} else if (callback === 'lang_tj' || msg.includes('тадж') || msg.includes('tajik')) {
  selectedLang = 'tj';
  langName = 'Тоҷикӣ';
}

// Сообщения на разных языках
const messages = {
  ru: `✅ Отлично! Язык установлен: Русский\n\nТеперь давайте познакомимся! Как вас зовут?`,
  uz: `✅ Juda yaxshi! Til tanlandi: O'zbek\n\nKeling, tanishamiz! Ismingiz nima?`,
  kg: `✅ Абдан жакшы! Тил тандалды: Кыргызча\n\nКелиңиз, таанышалы! Атыңыз ким?`,
  tj: `✅ Хеле хуб! Забон интихоб шуд: Тоҷикӣ\n\nБиёед шинос шавем! Номи шумо чист?`
};

return {
  ...input,
  response_message: messages[selectedLang],
  selected_language: selectedLang,
  language: selectedLang,
  show_language_buttons: false,
  interview_complete: false,
  extracted_data: input.known_data || {},
  update_language: true
};

// ============================================================
// ESCALATION HANDLER: Передача менеджеру
// ============================================================

const input = $json;

const escalationMessage = `🙋 Понимаю, что вам нужна помощь живого специалиста!\n\nЯ передам ваш запрос нашему HR-менеджеру. Он свяжется с вами в ближайшее время.\n\n📞 Или вы можете позвонить напрямую: +7 (XXX) XXX-XX-XX\n📧 Email: hr@besthotel.com\n\nСпасибо за терпение! 🙏`;

return {
  ...input,
  response_message: escalationMessage,
  show_language_buttons: false,
  interview_complete: false,
  extracted_data: input.known_data || {},
  needs_escalation: true
};
